+// yields at most one entity per node, and `void Start(), Stop();` is one node
+// declaring two methods.
+func cPlusPlusMemberDeclarationEntities(node *sitter.Node, src []byte, language, scope string) []Entity {
+	if language != "C++" || scope == "" {
+		return nil
