+	if end > 0 && end < len(src) && isIdent(src[end]) && isIdent(src[end-1]) {
+		return false
+	}
+	start := int(name.StartByte())
+	if start > 0 && start < len(src) && isIdent(src[start]) && isIdent(src[start-1]) {
+		return false
+	}
+	return true
+}
